#!/usr/bin/env python3
"""Independent finite-language span oracle; no regex engine or GNU reference."""
import argparse, itertools, json, os, random, subprocess, tempfile
from functools import lru_cache
from pathlib import Path

def lit(x): return ('byte', bytes([x]))
def cat(*x): return ('cat', x)
def alt(*x): return ('alt', x)
def repeat(x, lo, hi): return ('repeat', x, lo, hi)
A=lit(97); B=lit(98); DOT=('dot',); START=('start',); END=('end',)
PATTERNS=[('a|ab',alt(A,cat(A,B))), ('ab|a',alt(cat(A,B),A)),
 ('(ab|a)*',repeat(alt(cat(A,B),A),0,None)),
 ('(a|aa)+',repeat(alt(A,cat(A,A)),1,None)),
 ('(a?)*',repeat(repeat(A,0,1),0,None)),
 ('(a|b){0,2}',repeat(alt(A,B),0,2)),
 ('a{1,3}',repeat(A,1,3)), ('a*',repeat(A,0,None)),
 ('a?',repeat(A,0,1)), ('a*b*',cat(repeat(A,0,None),repeat(B,0,None))),
 ('a.*b',cat(A,repeat(DOT,0,None),B)),
 ('^|$',alt(START,END)), ('^a|b$',alt(cat(START,A),cat(B,END))),
 ('^a*$',cat(START,repeat(A,0,None),END)),
 ('(^|a)(b|$)',cat(alt(START,A),alt(B,END))),
 ('[^a]+',repeat(('not',b'a'),1,None)),
 ('[ab]+',repeat(('byte',b'ab'),1,None)),
 ('[[:upper:]]+',repeat(('byte',b'ABCDEFGHIJKLMNOPQRSTUVWXYZ'),1,None)),
 ('(a|)b?',cat(alt(A,('empty',)),repeat(B,0,1))),
 ('(.|a)*',repeat(alt(DOT,A),0,None)),
 ('\n|\r',alt(lit(10),lit(13))), ('',('empty',)),
 ('$',END), ('^',START), ('.',DOT)]
FOLD=bytes.maketrans(b'ABCDEFGHIJKLMNOPQRSTUVWXYZ',b'abcdefghijklmnopqrstuvwxyz')

def regex_oracle(source, ast, ignore=False):
 @lru_cache(None)
 def ends(node, start):
  kind=node[0]
  if kind=='empty': return frozenset([start])
  if kind=='start': return frozenset([start]) if start==0 else frozenset()
  if kind=='end': return frozenset([start]) if start==len(source) else frozenset()
  if kind=='dot': return frozenset([start+1]) if start<len(source) else frozenset()
  if kind in ('byte','not'):
   if start==len(source): return frozenset()
   ch=source[start:start+1]; choices=node[1]
   if ignore: ch=ch.translate(FOLD); choices=choices.translate(FOLD)
   ok=ch[0] in choices
   if kind=='not': ok=not ok
   return frozenset([start+1]) if ok else frozenset()
  if kind=='alt': return frozenset().union(*(ends(n,start) for n in node[1]))
  if kind=='cat':
   states=frozenset([start])
   for n in node[1]: states=frozenset().union(*(ends(n,p) for p in states))
   return states
  child,lo,hi=node[1:]; states=frozenset([start]); result=set()
  if lo==0: result.add(start)
  for k in range(1,(len(source)+lo+1 if hi is None else hi)+1):
   states=frozenset().union(*(ends(child,p) for p in states))
   if k>=lo: result.update(states)
  return frozenset(result)
 offset=0; spans=[]
 while offset<=len(source):
  possible=[(p,max(ends(ast,p))) for p in range(offset,len(source)+1) if ends(ast,p)]
  if not possible: break
  left,right=possible[0]; spans.append((left,right))
  if left==right: offset=right+1
  else: offset=right
 return spans

def output_for(source, spans, replacement):
 result=[]; last=0
 for left,right in spans:
  result.extend((source[last:left],replacement)); last=right
 result.append(source[last:]); return b''.join(result)

def check(program, prefix, cwd, source, pattern, replacement, expected, count, flags):
 file=cwd/'file'; file.write_bytes(source); file.chmod(0o640); before=file.stat()
 p=subprocess.run([program,*prefix,'--json',*flags,'file',os.fsdecode(pattern),os.fsdecode(replacement)],cwd=cwd,stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=4,env={**os.environ,'LC_ALL':'C.UTF-8'})
 got=(p.returncode,p.stdout,p.stderr,file.read_bytes())
 want=(0,json.dumps(dict(path='file',matches=count,replacements=count),separators=(',',':')).encode()+b'\n',b'',expected)
 assert got==want, (source,pattern,flags,want,got)
 after=file.stat(); assert (after.st_mode,after.st_uid,after.st_gid)==(before.st_mode,before.st_uid,before.st_gid)
 assert (after.st_ino!=before.st_ino)==bool(count)
 if not count: assert (after.st_mtime_ns,after.st_ctime_ns)==(before.st_mtime_ns,before.st_ctime_ns)
 assert sorted(p.name for p in cwd.iterdir())==['file']

def run(program,prefix):
 rng=random.Random(20261009); nregex=nfixed=0
 with tempfile.TemporaryDirectory(dir=os.environ['TMPDIR']) as d:
  cwd=Path(d)
  for _ in range(650):
   source=bytes(rng.choice(b'aAbB\n\r\xff') for _ in range(rng.randrange(17)))
   pattern,ast=rng.choice(PATTERNS); ignore=bool(rng.randrange(2)); replacement=rng.choice([b'',b'&\\1$\r\n',b'X'])
   spans=regex_oracle(source,ast,ignore)
   check(program,prefix,cwd,source,pattern.encode(),replacement,output_for(source,spans,replacement),len(spans),['-i'] if ignore else [])
   nregex+=1
  for size in range(4):
   for tup in itertools.product([0,10,13,65,97,255],repeat=size):
    source=bytes(tup)
    for pattern in [b'',b'A',b'\xff\r']:
     folded=source.translate(FOLD); pat=pattern.translate(FOLD)
     spans=[]
     if not pat: spans=[(i,i) for i in range(len(source)+1)]
     else:
      cursor=0
      while True:
       i=folded.find(pat,cursor)
       if i<0: break
       spans.append((i,i+len(pat))); cursor=i+len(pat)
     check(program,prefix,cwd,source,pattern,b'&\\\n',output_for(source,spans,b'&\\\n'),len(spans),['--fixed-strings','-i'])
     nfixed+=1
 print(json.dumps(dict(program=program,prefix=prefix,regex_cases=nregex,literal_cases=nfixed,passed=True)))
if __name__=='__main__':
 parser=argparse.ArgumentParser(); parser.add_argument('program'); parser.add_argument('--prefix',default=''); a=parser.parse_args(); run(str(Path(a.program).resolve()),[a.prefix] if a.prefix else [])
